        let loWeight = vec2<f32>(2.0) - pcfFraction;
        let hiWeight = vec2<f32>(1.0) + pcfFraction;
        let loOffset = vec2<f32>(-1.0) - pcfFraction + vec2<f32>(1.0) / loWeight;
